--
-- Name: enforce_contract_unit_property_exclusion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."enforce_contract_unit_property_exclusion"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NEW.is_deleted = false AND NEW.status = 1 THEN
    PERFORM lock_property_unit_scope(NEW.tenant_id, NEW.park_id, NEW.unit_id);
    IF EXISTS (
      SELECT 1
      FROM biz_property_operation_config config
      WHERE config.tenant_id = NEW.tenant_id
        AND config.park_id = NEW.park_id
        AND config.unit_id = NEW.unit_id
        AND config.is_deleted = false
        AND config.operating_mode = 'short_stay'
    ) THEN
      RAISE EXCEPTION 'short-stay unit cannot be linked to commercial leasing contract'
        USING ERRCODE = '23P01';
    END IF;
    IF EXISTS (
      SELECT 1
      FROM biz_property_occupancy occupancy
      WHERE occupancy.tenant_id = NEW.tenant_id
        AND occupancy.park_id = NEW.park_id
        AND occupancy.unit_id = NEW.unit_id
        AND occupancy.is_deleted = false
        AND (
          occupancy.status = 'active'
          OR (
            occupancy.status = 'held'
            AND (occupancy.hold_expires_at IS NULL OR occupancy.hold_expires_at > now())
          )
        )
        AND occupancy.start_at < ((NEW.end_date + 1)::timestamp AT TIME ZONE 'Asia/Shanghai')
        AND occupancy.end_at > (NEW.start_date::timestamp AT TIME ZONE 'Asia/Shanghai')
        AND NOT (
          occupancy.source_type = 'leasing_contract'
          AND occupancy.source_id = NEW.contract_id::text
        )
    ) THEN
      RAISE EXCEPTION 'commercial leasing contract conflicts with shared property occupancy'
        USING ERRCODE = '23P01';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_property_occupancy_contract_exclusion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."enforce_property_occupancy_contract_exclusion"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NEW.is_deleted = false AND NEW.status IN ('held', 'active') THEN
    PERFORM lock_property_unit_scope(NEW.tenant_id, NEW.park_id, NEW.unit_id);
    IF EXISTS (
      SELECT 1
      FROM rel_leasing_contract_unit relation
      JOIN biz_leasing_contract contract ON contract.id = relation.contract_id
      WHERE relation.tenant_id = NEW.tenant_id
        AND relation.park_id = NEW.park_id
        AND relation.unit_id = NEW.unit_id
        AND relation.is_deleted = false
        AND relation.status = 1
        AND contract.is_deleted = false
        AND contract.status NOT IN ('90', '91')
        AND (relation.start_date::timestamp AT TIME ZONE 'Asia/Shanghai') < NEW.end_at
        AND ((relation.end_date + 1)::timestamp AT TIME ZONE 'Asia/Shanghai') > NEW.start_at
        AND NOT (
          NEW.source_type = 'leasing_contract'
          AND NEW.source_id = contract.id::text
        )
    ) THEN
      RAISE EXCEPTION 'property occupancy conflicts with commercial leasing contract'
        USING ERRCODE = '23P01';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_guard_party_identity_assignment_audit_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."fn_guard_party_identity_assignment_audit_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
      DECLARE
        v_submission public.biz_party_identity_submission;
        v_previous integer;
        v_same_transaction boolean;
      BEGIN
        SELECT submission.*
        INTO v_submission
        FROM public.biz_party_identity_submission submission
        WHERE submission.tenant_id = NEW.tenant_id
          AND submission.park_id = NEW.park_id
          AND submission.id = NEW.submission_id
        FOR UPDATE;

        IF NOT FOUND THEN
          RAISE EXCEPTION 'property-resource-not-found' USING ERRCODE = 'P0002';
        END IF;

        IF NEW.legacy_backfill THEN
          IF NEW.action <> 'legacy-import'
             OR NEW.assignment_version_before <> 0
             OR NEW.assignment_version_after <> 1
          THEN
            RAISE EXCEPTION 'identity-assignment-audit-invalid' USING ERRCODE = '23514';
          END IF;
          RETURN NEW;
        END IF;

        SELECT coalesce(pg_catalog.max(audit.assignment_version_after), 0)
        INTO v_previous
        FROM public.biz_party_identity_assignment_audit audit
        WHERE audit.tenant_id = NEW.tenant_id
          AND audit.park_id = NEW.park_id
          AND audit.submission_id = NEW.submission_id;
        SELECT submission.xmin::text::bigint = pg_catalog.txid_current()
        INTO v_same_transaction
        FROM public.biz_party_identity_submission submission
        WHERE submission.tenant_id = NEW.tenant_id
          AND submission.park_id = NEW.park_id
          AND submission.id = NEW.submission_id;

        IF v_submission.status <> 'pending_verification'
           OR EXISTS (
             SELECT 1 FROM public.biz_party_identity_decision decision
             WHERE decision.tenant_id = NEW.tenant_id
               AND decision.park_id = NEW.park_id
               AND decision.submission_id = NEW.submission_id
           )
           OR v_submission.party_id <> NEW.party_id
           OR v_submission.identity_version <> NEW.identity_version
           OR v_submission.verification_queue_id <> NEW.verification_queue_id
           OR v_submission.eligibility_policy_hash <> NEW.eligibility_policy_hash
           OR v_previous <> NEW.assignment_version_before
           OR NEW.assignment_version_after <> NEW.assignment_version_before + 1
           OR v_submission.assignment_version <> NEW.assignment_version_after
           OR v_submission.assigned_verifier_id IS DISTINCT FROM NEW.to_verifier_id
           OR NOT coalesce(v_same_transaction, false)
        THEN
          RAISE EXCEPTION 'identity-assignment-audit-invalid' USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
      END;
      $$;


