    "version" integer DEFAULT 1 NOT NULL,
    "create_time" timestamp with time zone DEFAULT "clock_timestamp"() NOT NULL,
    "update_time" timestamp with time zone DEFAULT "clock_timestamp"() NOT NULL,
    CONSTRAINT "ck_biz_party_identity_submission_actor" CHECK ((("legacy_backfill" = true) OR (("drafted_by" IS NOT NULL) AND ("recorded_by" IS NOT NULL) AND ((("status")::"text" <> ALL ((ARRAY['pending_verification'::character varying, 'verified'::character varying, 'rejected'::character varying])::"text"[])) OR ("submitted_by" IS NOT NULL)) AND ((("status")::"text" <> ALL ((ARRAY['verified'::character varying, 'rejected'::character varying])::"text"[])) OR ("decided_by" IS NOT NULL)) AND ((("status")::"text" <> 'withdrawn'::"text") OR ("withdrawn_by" IS NOT NULL)) AND ((("status")::"text" <> 'superseded'::"text") OR ("superseded_by" IS NOT NULL))))),
    CONSTRAINT "ck_biz_party_identity_submission_anomaly" CHECK ((("legacy_actor_anomaly" = false) OR ("confidence" IS NOT NULL))),
