    CONSTRAINT "ck_biz_party_identity_submission_crypto_profile" CHECK (((("draft_hash_algorithm" IS NULL) AND ("draft_hash_version" IS NULL) AND ("draft_encryption_key_id" IS NULL) AND ("draft_payload_format_version" IS NULL)) OR ((("draft_hash_algorithm")::"text" = 'hmac-sha256'::"text") AND ("draft_hash_version" = 1) AND ("length"("btrim"(("draft_encryption_key_id")::"text")) > 0) AND ("draft_payload_format_version" = 1)))),
    CONSTRAINT "ck_biz_party_identity_submission_legacy" CHECK (((("legacy_backfill" = false) AND ("legacy_actor_anomaly" = false)) OR (("legacy_backfill" = true) AND (("source")::"text" ~~ 'legacy_%'::"text")))),
    CONSTRAINT "ck_biz_party_identity_submission_policy" CHECK ((((("status")::"text" = ANY ((ARRAY['draft'::character varying, 'superseded'::character varying])::"text"[])) AND ((("verification_queue_id" IS NULL) AND ("eligibility_policy_snapshot" IS NULL) AND ("eligibility_policy_hash" IS NULL)) OR (("verification_queue_id" IS NOT NULL) AND ("eligibility_policy_snapshot" IS NOT NULL) AND ("jsonb_typeof"("eligibility_policy_snapshot") = 'object'::"text") AND (("eligibility_policy_hash")::"text" ~ '^[0-9a-f]{64}$'::"text")))) OR ((("status")::"text" = ANY ((ARRAY['pending_verification'::character varying, 'verified'::character varying, 'rejected'::character varying, 'withdrawn'::character varying])::"text"[])) AND ("verification_queue_id" IS NOT NULL) AND ("eligibility_policy_snapshot" IS NOT NULL) AND ("jsonb_typeof"("eligibility_policy_snapshot") = 'object'::"text") AND (("eligibility_policy_hash")::"text" ~ '^[0-9a-f]{64}$'::"text")))),
    CONSTRAINT "ck_biz_party_identity_submission_queue_assignment" CHECK ((("verification_queue_id" IS NOT NULL) OR (("assignment_version" = 0) AND ("assigned_verifier_id" IS NULL)))),
    CONSTRAINT "ck_biz_party_identity_submission_snapshot_required" CHECK (((("status")::"text" = ANY ((ARRAY['draft'::character varying, 'superseded'::character varying])::"text"[])) OR ("snapshot_id" IS NOT NULL))),
    CONSTRAINT "ck_biz_party_identity_submission_status" CHECK ((("status")::"text" = ANY ((ARRAY['draft'::character varying, 'pending_verification'::character varying, 'verified'::character varying, 'rejected'::character varying, 'withdrawn'::character varying, 'superseded'::character varying])::"text"[]))),
    CONSTRAINT "ck_biz_party_identity_submission_supersedes_self" CHECK ((("supersedes_submission_id" IS NULL) OR ("supersedes_submission_id" <> "id"))),
    CONSTRAINT "ck_biz_party_identity_submission_times" CHECK ((((("status")::"text" = 'draft'::"text") AND ("submitted_at" IS NULL) AND ("decided_at" IS NULL) AND ("withdrawn_at" IS NULL) AND ("superseded_at" IS NULL)) OR ((("status")::"text" = 'pending_verification'::"text") AND ("submitted_at" IS NOT NULL) AND ("decided_at" IS NULL) AND ("withdrawn_at" IS NULL) AND ("superseded_at" IS NULL)) OR ((("status")::"text" = ANY ((ARRAY['verified'::character varying, 'rejected'::character varying])::"text"[])) AND ("submitted_at" IS NOT NULL) AND ("decided_at" IS NOT NULL) AND ("withdrawn_at" IS NULL) AND ("superseded_at" IS NULL)) OR ((("status")::"text" = 'withdrawn'::"text") AND ("submitted_at" IS NOT NULL) AND ("decided_at" IS NULL) AND ("withdrawn_at" IS NOT NULL) AND ("superseded_at" IS NULL)) OR ((("status")::"text" = 'superseded'::"text") AND ("superseded_at" IS NOT NULL)))),
    CONSTRAINT "ck_biz_party_identity_submission_versions" CHECK ((("identity_version" > 0) AND ("submission_attempt" > 0) AND ("assignment_version" >= 0) AND ("version" > 0)))
);


