--
-- Name: biz_property_migration_anomaly; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."biz_property_migration_anomaly" (
    "id" "uuid" DEFAULT "public"."uuid_generate_v4"() NOT NULL,
    "tenant_id" character varying(64) NOT NULL,
    "park_id" character varying(64) NOT NULL,
    "run_id" "uuid" NOT NULL,
    "checkpoint_id" "uuid" NOT NULL,
    "anomaly_kind" character varying(64) NOT NULL,
    "source_type" character varying(64) NOT NULL,
    "source_key" character varying(256) NOT NULL,
    "source_version" character varying(128),
    "expected_hash" character(64),
    "actual_hash" character(64),
    "details_redacted" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "status" character varying(16) DEFAULT 'open'::character varying NOT NULL,
    "detected_at" timestamp with time zone DEFAULT "clock_timestamp"() NOT NULL,
    "resolved_at" timestamp with time zone,
    "resolved_by" "uuid",
    "resolution_reference" character varying(256),
    "last_transition_by" "uuid",
    "last_transition_reason" character varying(1000),
    "version" integer DEFAULT 1 NOT NULL,
    CONSTRAINT "ck_biz_property_migration_anomaly_details" CHECK (("jsonb_typeof"("details_redacted") = 'object'::"text")),
    CONSTRAINT "ck_biz_property_migration_anomaly_hashes" CHECK (((("expected_hash" IS NULL) OR ("expected_hash" ~ '^[0-9a-f]{64}$'::"text")) AND (("actual_hash" IS NULL) OR ("actual_hash" ~ '^[0-9a-f]{64}$'::"text")))),
    CONSTRAINT "ck_biz_property_migration_anomaly_kind" CHECK ((("anomaly_kind")::"text" = ANY ((ARRAY['duplicate_active'::character varying, 'cross_scope'::character varying, 'pointer_mismatch'::character varying, 'hash_mismatch'::character varying, 'version_mismatch'::character varying, 'file_missing'::character varying, 'actor_missing'::character varying, 'audit_mismatch'::character varying, 'mutation_replay_mismatch'::character varying, 'projection_mismatch'::character varying, 'constraint_violation'::character varying])::"text"[]))),
    CONSTRAINT "ck_biz_property_migration_anomaly_resolution" CHECK ((((("status")::"text" = ANY ((ARRAY['open'::character varying, 'acknowledged'::character varying])::"text"[])) AND ("resolved_at" IS NULL) AND ("resolved_by" IS NULL) AND ("resolution_reference" IS NULL)) OR ((("status")::"text" = ANY ((ARRAY['resolved'::character varying, 'ignored'::character varying])::"text"[])) AND ("resolved_at" IS NOT NULL) AND ("resolved_by" IS NOT NULL) AND ("resolution_reference" IS NOT NULL)))),
    CONSTRAINT "ck_biz_property_migration_anomaly_status" CHECK ((("status")::"text" = ANY ((ARRAY['open'::character varying, 'acknowledged'::character varying, 'resolved'::character varying, 'ignored'::character varying])::"text"[]))),
    CONSTRAINT "ck_biz_property_migration_anomaly_transition_actor" CHECK (((("version" = 1) AND (("status")::"text" = 'open'::"text") AND ("last_transition_by" IS NULL) AND ("last_transition_reason" IS NULL)) OR (("version" > 1) AND ("last_transition_by" IS NOT NULL) AND ("length"(TRIM(BOTH FROM "last_transition_reason")) > 0)))),
    CONSTRAINT "ck_biz_property_migration_anomaly_version" CHECK (("version" > 0))
);


