--
-- Name: biz_ai_assignment_decision; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."biz_ai_assignment_decision" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" character varying(64) NOT NULL,
    "park_id" character varying(64) NOT NULL,
    "plan_id" "uuid" NOT NULL,
    "task_id" "uuid" NOT NULL,
    "candidate_user_id" "uuid" NOT NULL,
    "candidate_name" character varying(100) NOT NULL,
    "org_id" "uuid",
    "org_name" character varying(100),
    "role_codes" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
