    CONSTRAINT "ck_biz_party_identity_assignment_audit_anomaly" CHECK ((("legacy_actor_anomaly" = false) OR (("legacy_backfill" = true) AND ("confidence" IS NOT NULL) AND ("to_verifier_id" IS NULL)))),
    CONSTRAINT "ck_biz_party_identity_assignment_audit_hash" CHECK ((("eligibility_policy_hash")::"text" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "ck_biz_party_identity_assignment_audit_transition" CHECK ((((("action")::"text" = 'claim'::"text") AND ("from_verifier_id" IS NULL) AND ("to_verifier_id" IS NOT NULL)) OR ((("action")::"text" = 'reassign'::"text") AND ("from_verifier_id" IS NOT NULL) AND ("to_verifier_id" IS NOT NULL) AND ("from_verifier_id" <> "to_verifier_id") AND ("length"(TRIM(BOTH FROM "reason")) > 0)) OR ((("action")::"text" = 'revoke'::"text") AND ("from_verifier_id" IS NOT NULL) AND ("to_verifier_id" IS NULL) AND ("length"(TRIM(BOTH FROM "reason")) > 0)) OR ((("action")::"text" = 'legacy-import'::"text") AND ("from_verifier_id" IS NULL) AND ("assignment_version_before" = 0) AND ("assignment_version_after" = 1)))),
    CONSTRAINT "ck_biz_party_identity_assignment_audit_versions" CHECK ((("assignment_version_before" >= 0) AND ("assignment_version_after" = ("assignment_version_before" + 1))))
);


