--
-- Name: biz_party_identity_decision; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."biz_party_identity_decision" (
    "id" "uuid" DEFAULT "public"."uuid_generate_v4"() NOT NULL,
    "tenant_id" character varying(64) NOT NULL,
    "park_id" character varying(64) NOT NULL,
    "party_id" "uuid" NOT NULL,
    "identity_version" bigint NOT NULL,
    "submission_id" "uuid" NOT NULL,
    "snapshot_id" "uuid" NOT NULL,
    "verification_queue_id" "uuid" NOT NULL,
    "assignment_version" integer NOT NULL,
    "eligibility_policy_hash" character varying(64) NOT NULL,
    "decision" character varying(16) NOT NULL,
    "reason" character varying(500),
    "decided_by" "uuid",
    "decided_at" timestamp with time zone NOT NULL,
    "submission_version" integer NOT NULL,
    "source" character varying(32) NOT NULL,
    "confidence" character varying(32),
    "legacy_backfill" boolean DEFAULT false NOT NULL,
    "legacy_actor_anomaly" boolean DEFAULT false NOT NULL,
    "create_time" timestamp with time zone DEFAULT "clock_timestamp"() NOT NULL,
    CONSTRAINT "ck_biz_party_identity_decision_actor" CHECK (((("legacy_backfill" = false) AND ("decided_by" IS NOT NULL) AND ("legacy_actor_anomaly" = false)) OR (("legacy_backfill" = true) AND (("source")::"text" ~~ 'legacy_%'::"text")))),
    CONSTRAINT "ck_biz_party_identity_decision_actor_presence" CHECK ((("decided_by" IS NOT NULL) OR ("legacy_actor_anomaly" = true))),
    CONSTRAINT "ck_biz_party_identity_decision_anomaly" CHECK ((("legacy_actor_anomaly" = false) OR ("confidence" IS NOT NULL))),
    CONSTRAINT "ck_biz_party_identity_decision_hash" CHECK ((("eligibility_policy_hash")::"text" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "ck_biz_party_identity_decision_reason" CHECK (((("decision")::"text" <> 'rejected'::"text") OR ("length"(TRIM(BOTH FROM "reason")) > 0))),
    CONSTRAINT "ck_biz_party_identity_decision_value" CHECK ((("decision")::"text" = ANY ((ARRAY['verified'::character varying, 'rejected'::character varying])::"text"[]))),
    CONSTRAINT "ck_biz_party_identity_decision_versions" CHECK ((("submission_version" > 0) AND ("assignment_version" > 0)))
);


