    "encryption_key_id" character varying(128) NOT NULL,
    "payload_format_version" integer NOT NULL,
    "captured_by" "uuid",
    "captured_at" timestamp with time zone NOT NULL,
    "source" character varying(32) NOT NULL,
    "confidence" character varying(32),
    "legacy_backfill" boolean DEFAULT false NOT NULL,
    "legacy_actor_anomaly" boolean DEFAULT false NOT NULL,
    "create_time" timestamp with time zone DEFAULT "clock_timestamp"() NOT NULL,
    CONSTRAINT "ck_biz_party_identity_snapshot_actor" CHECK (((("legacy_backfill" = false) AND ("captured_by" IS NOT NULL) AND ("legacy_actor_anomaly" = false)) OR (("legacy_backfill" = true) AND (("source")::"text" ~~ 'legacy_%'::"text")))),
    CONSTRAINT "ck_biz_party_identity_snapshot_actor_presence" CHECK ((("captured_by" IS NOT NULL) OR ("legacy_actor_anomaly" = true))),
    CONSTRAINT "ck_biz_party_identity_snapshot_anomaly" CHECK ((("legacy_actor_anomaly" = false) OR (("legacy_backfill" = true) AND ("confidence" IS NOT NULL)))),
    CONSTRAINT "ck_biz_party_identity_snapshot_hash_version" CHECK (("hash_version" > 0)),
    CONSTRAINT "ck_biz_party_identity_snapshot_identity_version" CHECK (("identity_version" > 0)),
    CONSTRAINT "ck_biz_party_identity_snapshot_payload_version" CHECK (("payload_format_version" > 0)),
    CONSTRAINT "ck_biz_party_identity_snapshot_revision" CHECK (("snapshot_revision" > 0))
);


