    "update_time" timestamp with time zone DEFAULT "clock_timestamp"() NOT NULL,
    CONSTRAINT "ck_biz_party_identity_queue_legacy" CHECK (((("legacy_backfill" = false) AND ("legacy_anomaly" = false)) OR (("legacy_backfill" = true) AND (("queue_code")::"text" ~~ 'legacy-%'::"text")))),
    CONSTRAINT "ck_biz_party_identity_queue_policy_hash" CHECK ((("eligibility_policy_hash")::"text" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "ck_biz_party_identity_queue_policy_object" CHECK (("jsonb_typeof"("eligibility_policy_snapshot") = 'object'::"text")),
    CONSTRAINT "ck_biz_party_identity_queue_status" CHECK ((("status")::"text" = ANY ((ARRAY['active'::character varying, 'inactive'::character varying])::"text"[]))),
    CONSTRAINT "ck_biz_party_identity_queue_versions" CHECK ((("eligibility_policy_version" > 0) AND ("version" > 0)))
);


