--
-- Name: biz_property_approval_request; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."biz_property_approval_request" (
    "id" "uuid" DEFAULT "public"."uuid_generate_v4"() NOT NULL,
    "tenant_id" character varying(64) NOT NULL,
    "park_id" character varying(64) NOT NULL,
    "action_id" character varying(128) NOT NULL,
    "source_type" character varying(64) NOT NULL,
    "source_id" "uuid" NOT NULL,
    "source_expected_version" integer NOT NULL,
    "requester_id" "uuid" NOT NULL,
    "submitter_id" "uuid" NOT NULL,
    "client_idempotency_key" character varying(128) NOT NULL,
    "business_intent_key" character varying(128) NOT NULL,
    "canonical_payload" "jsonb" NOT NULL,
    "payload_schema_version" integer NOT NULL,
    "payload_hash" character(64) NOT NULL,
    "amount" numeric(18,2),
    "currency" character varying(8),
    "policy_id" "uuid" NOT NULL,
    "policy_version" integer NOT NULL,
    "policy_hash" character(64) NOT NULL,
    "decision_status" character varying(32) DEFAULT 'draft'::character varying NOT NULL,
    "execution_status" character varying(32) DEFAULT 'not_started'::character varying NOT NULL,
    "decision_version" integer DEFAULT 1 NOT NULL,
    "execution_version" integer DEFAULT 1 NOT NULL,
    "execution_idempotency_key" character varying(128) NOT NULL,
    "claim_epoch" bigint DEFAULT 0 NOT NULL,
    "claim_token" "uuid",
    "worker_id" character varying(128),
    "lease_expires_at" timestamp with time zone,
    "heartbeat_at" timestamp with time zone,
    "attempt_count" integer DEFAULT 0 NOT NULL,
    "next_retry_at" timestamp with time zone,
    "reconcile_required" boolean DEFAULT false NOT NULL,
    "last_error_category" character varying(32),
    "last_error_code" character varying(128),
    "last_error_redacted_message" character varying(500),
    "infra_exhausted_at" timestamp with time zone,
    "submitted_at" timestamp with time zone,
    "decided_at" timestamp with time zone,
    "executed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "clock_timestamp"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "clock_timestamp"() NOT NULL,
    CONSTRAINT "biz_property_approval_request_attempt_count_check" CHECK (("attempt_count" >= 0)),
    CONSTRAINT "biz_property_approval_request_canonical_payload_check" CHECK (("jsonb_typeof"("canonical_payload") = 'object'::"text")),
    CONSTRAINT "biz_property_approval_request_claim_epoch_check" CHECK (("claim_epoch" >= 0)),
    CONSTRAINT "biz_property_approval_request_decision_version_check" CHECK (("decision_version" > 0)),
    CONSTRAINT "biz_property_approval_request_execution_version_check" CHECK (("execution_version" > 0)),
    CONSTRAINT "biz_property_approval_request_payload_hash_check" CHECK (("payload_hash" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "biz_property_approval_request_payload_schema_version_check" CHECK (("payload_schema_version" > 0)),
    CONSTRAINT "biz_property_approval_request_policy_hash_check" CHECK (("policy_hash" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "biz_property_approval_request_policy_version_check" CHECK (("policy_version" > 0)),
    CONSTRAINT "biz_property_approval_request_source_expected_version_check" CHECK (("source_expected_version" > 0)),
    CONSTRAINT "ck_biz_property_approval_request_amount_currency" CHECK (((("amount" IS NULL) AND ("currency" IS NULL)) OR (("amount" IS NOT NULL) AND ("amount" >= (0)::numeric) AND (("currency")::"text" ~ '^[A-Z]{3}$'::"text")))),
    CONSTRAINT "ck_biz_property_approval_request_claim" CHECK ((((("execution_status")::"text" = 'executing'::"text") AND ("claim_token" IS NOT NULL) AND ("worker_id" IS NOT NULL) AND ("lease_expires_at" IS NOT NULL) AND ("heartbeat_at" IS NOT NULL)) OR ((("execution_status")::"text" <> 'executing'::"text") AND ("claim_token" IS NULL) AND ("worker_id" IS NULL) AND ("lease_expires_at" IS NULL) AND ("heartbeat_at" IS NULL)))),
    CONSTRAINT "ck_biz_property_approval_request_decision_status" CHECK ((("decision_status")::"text" = ANY ((ARRAY['draft'::character varying, 'submitted'::character varying, 'pending_approval'::character varying, 'approved'::character varying, 'rejected'::character varying, 'withdrawn'::character varying, 'expired'::character varying])::"text"[]))),
    CONSTRAINT "ck_biz_property_approval_request_executed" CHECK (((("execution_status")::"text" = 'executed'::"text") = ("executed_at" IS NOT NULL))),
    CONSTRAINT "ck_biz_property_approval_request_execution_failed" CHECK (((("execution_status")::"text" <> 'execution_failed'::"text") OR (("last_error_category" IS NOT NULL) AND ("last_error_code" IS NOT NULL)))),
    CONSTRAINT "ck_biz_property_approval_request_execution_status" CHECK ((("execution_status")::"text" = ANY ((ARRAY['not_started'::character varying, 'executing'::character varying, 'retry_wait'::character varying, 'executed'::character varying, 'execution_failed'::character varying, 'infra_exhausted'::character varying, 'not_required'::character varying])::"text"[]))),
    CONSTRAINT "ck_biz_property_approval_request_infra_exhausted" CHECK (((("execution_status")::"text" = 'infra_exhausted'::"text") = (("infra_exhausted_at" IS NOT NULL) AND (("last_error_category")::"text" = 'infra'::"text") AND ("last_error_code" IS NOT NULL)))),
    CONSTRAINT "ck_biz_property_approval_request_retry" CHECK (((("execution_status")::"text" = 'retry_wait'::"text") = ("next_retry_at" IS NOT NULL))),
    CONSTRAINT "ck_biz_property_approval_request_status_pair" CHECK ((((("decision_status")::"text" = ANY ((ARRAY['draft'::character varying, 'submitted'::character varying, 'pending_approval'::character varying])::"text"[])) AND (("execution_status")::"text" = 'not_started'::"text")) OR ((("decision_status")::"text" = 'approved'::"text") AND (("execution_status")::"text" = ANY ((ARRAY['not_started'::character varying, 'executing'::character varying, 'retry_wait'::character varying, 'executed'::character varying, 'execution_failed'::character varying, 'infra_exhausted'::character varying])::"text"[]))) OR ((("decision_status")::"text" = ANY ((ARRAY['rejected'::character varying, 'withdrawn'::character varying, 'expired'::character varying])::"text"[])) AND (("execution_status")::"text" = 'not_required'::"text"))))
);


