--
-- Name: biz_property_approval_stage; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."biz_property_approval_stage" (
    "id" "uuid" DEFAULT "public"."uuid_generate_v4"() NOT NULL,
    "tenant_id" character varying(64) NOT NULL,
    "park_id" character varying(64) NOT NULL,
    "request_id" "uuid" NOT NULL,
    "stage_code" character varying(64) NOT NULL,
    "stage_ordinal" smallint NOT NULL,
    "eligibility_policy_snapshot" "jsonb" NOT NULL,
    "eligibility_policy_version" integer NOT NULL,
    "eligibility_policy_hash" character(64) NOT NULL,
    "required_count" smallint NOT NULL,
    "approved_count" smallint DEFAULT 0 NOT NULL,
    "rejected_count" smallint DEFAULT 0 NOT NULL,
    "stage_status" character varying(24) DEFAULT 'pending'::character varying NOT NULL,
    "version" integer DEFAULT 1 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "clock_timestamp"() NOT NULL,
    CONSTRAINT "biz_property_approval_stage_approved_count_check" CHECK (("approved_count" >= 0)),
    CONSTRAINT "biz_property_approval_stage_eligibility_policy_hash_check" CHECK (("eligibility_policy_hash" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "biz_property_approval_stage_eligibility_policy_snapshot_check" CHECK (("jsonb_typeof"("eligibility_policy_snapshot") = 'object'::"text")),
    CONSTRAINT "biz_property_approval_stage_eligibility_policy_version_check" CHECK (("eligibility_policy_version" > 0)),
    CONSTRAINT "biz_property_approval_stage_rejected_count_check" CHECK (("rejected_count" >= 0)),
    CONSTRAINT "biz_property_approval_stage_required_count_check" CHECK (("required_count" > 0)),
    CONSTRAINT "biz_property_approval_stage_stage_ordinal_check" CHECK (("stage_ordinal" > 0)),
    CONSTRAINT "biz_property_approval_stage_version_check" CHECK (("version" > 0)),
    CONSTRAINT "ck_biz_property_approval_stage_counts" CHECK ((("approved_count" <= "required_count") AND ("rejected_count" <= "required_count"))),
    CONSTRAINT "ck_biz_property_approval_stage_status" CHECK ((("stage_status")::"text" = ANY ((ARRAY['pending'::character varying, 'approved'::character varying, 'rejected'::character varying, 'expired'::character varying])::"text"[])))
);


