--
-- Name: biz_property_event_dlq; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."biz_property_event_dlq" (
    "id" "uuid" DEFAULT "public"."uuid_generate_v4"() NOT NULL,
    "tenant_id" character varying(64) NOT NULL,
    "park_id" character varying(64) NOT NULL,
    "original_event_id" "uuid" NOT NULL,
    "consumer_name" character varying(128) NOT NULL,
    "notification_delivery_id" "uuid",
    "payload_hash" character(64) NOT NULL,
    "failure_side" character varying(16) NOT NULL,
    "error_category" character varying(32) NOT NULL,
    "error_code" character varying(128) NOT NULL,
    "attempt_count" integer NOT NULL,
    "version" integer DEFAULT 1 NOT NULL,
    "first_failed_at" timestamp with time zone NOT NULL,
    "last_failed_at" timestamp with time zone NOT NULL,
    "incident_id" character varying(128),
    "last_replay_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "clock_timestamp"() NOT NULL,
    "status" character varying(16) DEFAULT 'active'::character varying NOT NULL,
    CONSTRAINT "biz_property_event_dlq_attempt_count_check" CHECK (("attempt_count" > 0)),
    CONSTRAINT "biz_property_event_dlq_payload_hash_check" CHECK (("payload_hash" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "biz_property_event_dlq_version_check" CHECK (("version" > 0)),
    CONSTRAINT "ck_biz_property_event_dlq_delivery_side" CHECK ((("notification_delivery_id" IS NULL) OR (("failure_side")::"text" = 'consumer'::"text"))),
    CONSTRAINT "ck_biz_property_event_dlq_failure_side" CHECK ((("failure_side")::"text" = ANY ((ARRAY['publisher'::character varying, 'consumer'::character varying])::"text"[]))),
    CONSTRAINT "ck_biz_property_event_dlq_publisher" CHECK (((("failure_side")::"text" = 'publisher'::"text") = (("consumer_name")::"text" = '__publisher__'::"text"))),
    CONSTRAINT "ck_biz_property_event_dlq_status" CHECK ((("status")::"text" = ANY ((ARRAY['active'::character varying, 'replaying'::character varying, 'resolved'::character varying, 'quarantined'::character varying])::"text"[])))
);


