    "occurred_at" timestamp with time zone DEFAULT "clock_timestamp"() NOT NULL,
    CONSTRAINT "ck_biz_property_migration_anomaly_audit_from" CHECK ((("from_status")::"text" = ANY ((ARRAY['open'::character varying, 'acknowledged'::character varying, 'resolved'::character varying, 'ignored'::character varying])::"text"[]))),
    CONSTRAINT "ck_biz_property_migration_anomaly_audit_reason" CHECK (("length"(TRIM(BOTH FROM "reason")) > 0)),
    CONSTRAINT "ck_biz_property_migration_anomaly_audit_to" CHECK ((("to_status")::"text" = ANY ((ARRAY['acknowledged'::character varying, 'resolved'::character varying, 'ignored'::character varying])::"text"[]))),
    CONSTRAINT "ck_biz_property_migration_anomaly_audit_version" CHECK ((("expected_version" > 0) AND ("resulting_version" = ("expected_version" + 1))))
);


