    CONSTRAINT "biz_property_notification_delivery_version_check" CHECK (("version" > 0)),
    CONSTRAINT "ck_biz_property_notification_delivery_attempts" CHECK ((("attempt_count" <= "max_attempts") AND ((("delivery_status")::"text" <> 'delivery_exhausted'::"text") OR ("attempt_count" = "max_attempts")) AND ((("delivery_status")::"text" <> 'delivery_failed'::"text") OR ("attempt_count" < "max_attempts")))),
    CONSTRAINT "ck_biz_property_notification_delivery_channel" CHECK ((("channel")::"text" = ANY ((ARRAY['in_app'::character varying, 'email'::character varying, 'sms'::character varying, 'webhook'::character varying])::"text"[]))),
    CONSTRAINT "ck_biz_property_notification_delivery_claim" CHECK ((((("delivery_status")::"text" = 'delivering'::"text") AND ("claim_token" IS NOT NULL) AND ("lease_expires_at" IS NOT NULL)) OR ((("delivery_status")::"text" <> 'delivering'::"text") AND ("claim_token" IS NULL) AND ("lease_expires_at" IS NULL)))),
    CONSTRAINT "ck_biz_property_notification_delivery_delivered" CHECK (((("delivery_status")::"text" = 'delivered'::"text") = ("delivered_at" IS NOT NULL))),
    CONSTRAINT "ck_biz_property_notification_delivery_exhausted" CHECK (((("delivery_status")::"text" = 'delivery_exhausted'::"text") = ("exhausted_at" IS NOT NULL))),
    CONSTRAINT "ck_biz_property_notification_delivery_retry" CHECK (((("delivery_status")::"text" = 'delivery_failed'::"text") = ("next_retry_at" IS NOT NULL))),
    CONSTRAINT "ck_biz_property_notification_delivery_status" CHECK ((("delivery_status")::"text" = ANY ((ARRAY['pending'::character varying, 'delivering'::character varying, 'delivered'::character varying, 'delivery_failed'::character varying, 'delivery_exhausted'::character varying])::"text"[])))
);


