-- Name: biz_property_occupancy; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."biz_property_occupancy" (
    "id" "uuid" DEFAULT "public"."uuid_generate_v4"() NOT NULL,
    "tenant_id" character varying(64) NOT NULL,
    "park_id" character varying(64) NOT NULL,
    "unit_id" "uuid" NOT NULL,
    "source_domain" character varying(32) NOT NULL,
    "source_type" character varying(64) NOT NULL,
    "source_id" character varying(64) NOT NULL,
    "start_at" timestamp with time zone NOT NULL,
    "end_at" timestamp with time zone NOT NULL,
    "status" character varying(32) NOT NULL,
    "hold_expires_at" timestamp with time zone,
    "idempotency_key" character varying(128),
    "release_reason" character varying(500),
    "released_at" timestamp with time zone,
    "create_by" "uuid",
    "create_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    "update_by" "uuid",
    "update_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    "is_deleted" boolean DEFAULT false NOT NULL,
    "version" integer DEFAULT 1 NOT NULL,
    "remark" character varying(500),
    CONSTRAINT "ck_property_occupancy_domain" CHECK ((("source_domain")::"text" = ANY ((ARRAY['commercial_leasing'::character varying, 'homestay'::character varying, 'housing_rental'::character varying, 'maintenance'::character varying, 'operations'::character varying])::"text"[]))),
    CONSTRAINT "ck_property_occupancy_hold_expiry" CHECK (((("status")::"text" <> 'held'::"text") OR ("hold_expires_at" IS NOT NULL))),
    CONSTRAINT "ck_property_occupancy_period" CHECK (("start_at" < "end_at")),
    CONSTRAINT "ck_property_occupancy_status" CHECK ((("status")::"text" = ANY ((ARRAY['held'::character varying, 'active'::character varying, 'released'::character varying, 'completed'::character varying, 'cancelled'::character varying])::"text"[])))
);


--
-- Name: biz_property_operation_config; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."biz_property_operation_config" (
    "id" "uuid" DEFAULT "public"."uuid_generate_v4"() NOT NULL,
    "tenant_id" character varying(64) NOT NULL,
    "park_id" character varying(64) NOT NULL,
    "unit_id" "uuid" NOT NULL,
    "operating_mode" character varying(32) DEFAULT 'none'::character varying NOT NULL,
    "operating_status" character varying(32) DEFAULT 'enabled'::character varying NOT NULL,
    "effective_time" timestamp with time zone,
    "suspend_reason" character varying(500),
    "create_by" "uuid",
    "create_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    "update_by" "uuid",
    "update_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    "is_deleted" boolean DEFAULT false NOT NULL,
    "version" integer DEFAULT 1 NOT NULL,
    "remark" character varying(500),
    CONSTRAINT "ck_property_operation_mode" CHECK ((("operating_mode")::"text" = ANY ((ARRAY['none'::character varying, 'short_stay'::character varying, 'long_rent'::character varying])::"text"[]))),
    CONSTRAINT "ck_property_operation_status" CHECK ((("operating_status")::"text" = ANY ((ARRAY['enabled'::character varying, 'suspended'::character varying, 'disabled'::character varying])::"text"[]))),
    CONSTRAINT "ck_property_operation_suspend_reason" CHECK (((("operating_status")::"text" = 'enabled'::"text") OR (NULLIF("btrim"(("suspend_reason")::"text"), ''::"text") IS NOT NULL)))
);


--
-- Name: biz_property_outbox; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."biz_property_outbox" (
    "event_id" "uuid" NOT NULL,
    "tenant_id" character varying(64) NOT NULL,
    "park_id" character varying(64) NOT NULL,
    "event_type" character varying(128) NOT NULL,
    "event_version" integer NOT NULL,
    "aggregate_type" character varying(64) NOT NULL,
    "aggregate_id" "uuid" NOT NULL,
    "aggregate_version" integer NOT NULL,
    "ordering_key" character varying(256) NOT NULL,
    "sequence" bigint NOT NULL,
    "event_ordinal" integer NOT NULL,
    "approval_request_id" "uuid",
    "execution_idempotency_key" character varying(128),
    "payload" "jsonb" NOT NULL,
    "payload_hash" character(64) NOT NULL,
    "status" character varying(16) DEFAULT 'pending'::character varying NOT NULL,
    "claim_epoch" bigint DEFAULT 0 NOT NULL,
    "claim_token" "uuid",
    "worker_id" character varying(128),
    "lease_expires_at" timestamp with time zone,
    "attempt_count" integer DEFAULT 0 NOT NULL,
    "next_retry_at" timestamp with time zone,
    "published_at" timestamp with time zone,
    "dlq_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "clock_timestamp"() NOT NULL,
    CONSTRAINT "biz_property_outbox_aggregate_version_check" CHECK (("aggregate_version" > 0)),
    CONSTRAINT "biz_property_outbox_attempt_count_check" CHECK (("attempt_count" >= 0)),
    CONSTRAINT "biz_property_outbox_claim_epoch_check" CHECK (("claim_epoch" >= 0)),
    CONSTRAINT "biz_property_outbox_event_ordinal_check" CHECK (("event_ordinal" >= 0)),
    CONSTRAINT "biz_property_outbox_event_version_check" CHECK (("event_version" > 0)),
    CONSTRAINT "biz_property_outbox_payload_check" CHECK (("jsonb_typeof"("payload") = 'object'::"text")),
    CONSTRAINT "biz_property_outbox_payload_hash_check" CHECK (("payload_hash" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "biz_property_outbox_sequence_check" CHECK (("sequence" > 0)),
    CONSTRAINT "ck_biz_property_outbox_claim" CHECK ((((("status")::"text" = 'publishing'::"text") AND ("claim_token" IS NOT NULL) AND ("worker_id" IS NOT NULL) AND ("lease_expires_at" IS NOT NULL)) OR ((("status")::"text" <> 'publishing'::"text") AND ("claim_token" IS NULL) AND ("worker_id" IS NULL) AND ("lease_expires_at" IS NULL)))),
    CONSTRAINT "ck_biz_property_outbox_dlq" CHECK (((("status")::"text" = 'dlq'::"text") = ("dlq_at" IS NOT NULL))),
    CONSTRAINT "ck_biz_property_outbox_published" CHECK (((("status")::"text" = 'published'::"text") = ("published_at" IS NOT NULL))),
    CONSTRAINT "ck_biz_property_outbox_retry" CHECK (((("status")::"text" = 'retry_wait'::"text") = ("next_retry_at" IS NOT NULL))),
    CONSTRAINT "ck_biz_property_outbox_status" CHECK ((("status")::"text" = ANY ((ARRAY['pending'::character varying, 'publishing'::character varying, 'retry_wait'::character varying, 'published'::character varying, 'dlq'::character varying])::"text"[])))
);


