-- Name: biz_property_runtime_checkpoint; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."biz_property_runtime_checkpoint" (
    "id" "uuid" DEFAULT "public"."uuid_generate_v4"() NOT NULL,
    "tenant_id" character varying(64) NOT NULL,
    "park_id" character varying(64) NOT NULL,
    "checkpoint_kind" character varying(64) NOT NULL,
    "checkpoint_key" character varying(256) NOT NULL,
    "checkpoint_version" integer DEFAULT 1 NOT NULL,
    "cursor_value" character varying(512),
    "anomaly_count" bigint DEFAULT 0 NOT NULL,
    "status" character varying(16) DEFAULT 'disabled'::character varying NOT NULL,
    "evidence_hash" character(64),
    "last_run_id" "uuid",
    "updated_by" "uuid",
    "updated_at" timestamp with time zone DEFAULT "clock_timestamp"() NOT NULL,
    "version" integer DEFAULT 1 NOT NULL,
    CONSTRAINT "ck_biz_property_runtime_checkpoint_counts" CHECK ((("checkpoint_version" > 0) AND ("anomaly_count" >= 0) AND ("version" > 0))),
    CONSTRAINT "ck_biz_property_runtime_checkpoint_evidence" CHECK ((("evidence_hash" IS NULL) OR ("evidence_hash" ~ '^[0-9a-f]{64}$'::"text"))),
    CONSTRAINT "ck_biz_property_runtime_checkpoint_kind" CHECK ((("checkpoint_kind")::"text" = ANY ((ARRAY['backfill'::character varying, 'change_capture'::character varying, 'mutation_replay'::character varying, 'shadow_compare'::character varying, 'reconcile'::character varying, 'constraint_validate'::character varying])::"text"[]))),
    CONSTRAINT "ck_biz_property_runtime_checkpoint_status" CHECK ((("status")::"text" = ANY ((ARRAY['disabled'::character varying, 'running'::character varying, 'paused'::character varying, 'completed'::character varying, 'failed'::character varying])::"text"[])))
);


