--
-- Name: biz_property_task_assignment; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."biz_property_task_assignment" (
    "id" "uuid" DEFAULT "public"."uuid_generate_v4"() NOT NULL,
    "tenant_id" character varying(64) NOT NULL,
    "park_id" character varying(64) NOT NULL,
    "task_key" character varying(256) NOT NULL,
    "task_key_version" integer NOT NULL,
    "task_kind" character varying(64) NOT NULL,
    "source_type" character varying(64) NOT NULL,
    "source_id" "uuid" NOT NULL,
    "source_version_at_generation" integer NOT NULL,
    "assignment_status" character varying(16) DEFAULT 'open'::character varying NOT NULL,
    "assignee_id" "uuid",
    "claim_epoch" bigint DEFAULT 0 NOT NULL,
    "claim_token" "uuid",
    "version" integer DEFAULT 1 NOT NULL,
    "claimed_at" timestamp with time zone,
    "started_at" timestamp with time zone,
    "blocked_reason" character varying(1000),
    "blocked_until" timestamp with time zone,
    "outcome_code" character varying(64),
    "outcome_source_version" integer,
    "outcome_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "clock_timestamp"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "clock_timestamp"() NOT NULL,
    "is_deleted" boolean DEFAULT false NOT NULL,
    CONSTRAINT "biz_property_task_assignment_claim_epoch_check" CHECK (("claim_epoch" >= 0)),
    CONSTRAINT "biz_property_task_assignment_outcome_source_version_check" CHECK (("outcome_source_version" > 0)),
    CONSTRAINT "biz_property_task_assignment_source_version_at_generation_check" CHECK (("source_version_at_generation" > 0)),
    CONSTRAINT "biz_property_task_assignment_task_key_version_check" CHECK (("task_key_version" > 0)),
    CONSTRAINT "biz_property_task_assignment_version_check" CHECK (("version" > 0)),
    CONSTRAINT "ck_biz_property_task_assignment_active" CHECK (((("assignment_status")::"text" <> ALL ((ARRAY['claimed'::character varying, 'in_progress'::character varying, 'blocked'::character varying])::"text"[])) OR (("assignee_id" IS NOT NULL) AND ("claim_token" IS NOT NULL) AND ("claimed_at" IS NOT NULL)))),
    CONSTRAINT "ck_biz_property_task_assignment_blocked" CHECK (((("assignment_status")::"text" = 'blocked'::"text") = ("blocked_reason" IS NOT NULL))),
    CONSTRAINT "ck_biz_property_task_assignment_open" CHECK (((("assignment_status")::"text" <> 'open'::"text") OR (("assignee_id" IS NULL) AND ("claim_token" IS NULL) AND ("claimed_at" IS NULL)))),
    CONSTRAINT "ck_biz_property_task_assignment_status" CHECK ((("assignment_status")::"text" = ANY ((ARRAY['open'::character varying, 'claimed'::character varying, 'in_progress'::character varying, 'blocked'::character varying, 'closed'::character varying, 'cancelled'::character varying])::"text"[]))),
    CONSTRAINT "ck_biz_property_task_assignment_terminal" CHECK (((("assignment_status")::"text" = ANY ((ARRAY['closed'::character varying, 'cancelled'::character varying])::"text"[])) = (("outcome_code" IS NOT NULL) AND ("outcome_source_version" IS NOT NULL) AND ("outcome_at" IS NOT NULL))))
);


