--

CREATE TABLE "public"."biz_property_task_assignment_audit" (
    "id" "uuid" DEFAULT "public"."uuid_generate_v4"() NOT NULL,
    "tenant_id" character varying(64) NOT NULL,
    "park_id" character varying(64) NOT NULL,
    "assignment_id" "uuid" NOT NULL,
    "actor_id" "uuid",
    "action_id" character varying(128) NOT NULL,
    "from_status" character varying(16) NOT NULL,
    "to_status" character varying(16) NOT NULL,
    "from_version" integer NOT NULL,
    "to_version" integer NOT NULL,
    "reason" character varying(1000),
    "payload_hash" character(64) NOT NULL,
    "occurred_at" timestamp with time zone DEFAULT "clock_timestamp"() NOT NULL,
    CONSTRAINT "biz_property_task_assignment_audit_from_version_check" CHECK (("from_version" > 0)),
    CONSTRAINT "biz_property_task_assignment_audit_payload_hash_check" CHECK (("payload_hash" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "biz_property_task_assignment_audit_to_version_check" CHECK (("to_version" > 0)),
    CONSTRAINT "ck_biz_property_task_assignment_audit_status" CHECK (((("from_status")::"text" = ANY ((ARRAY['open'::character varying, 'claimed'::character varying, 'in_progress'::character varying, 'blocked'::character varying, 'closed'::character varying, 'cancelled'::character varying])::"text"[])) AND (("to_status")::"text" = ANY ((ARRAY['open'::character varying, 'claimed'::character varying, 'in_progress'::character varying, 'blocked'::character varying, 'closed'::character varying, 'cancelled'::character varying])::"text"[])))),
    CONSTRAINT "ck_biz_property_task_assignment_audit_version" CHECK (("to_version" = ("from_version" + 1)))
);


