--
-- Name: biz_property_task_projection; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."biz_property_task_projection" (
    "id" "uuid" DEFAULT "public"."uuid_generate_v4"() NOT NULL,
    "tenant_id" character varying(64) NOT NULL,
    "park_id" character varying(64) NOT NULL,
    "head_id" "uuid" NOT NULL,
    "task_id" "uuid" NOT NULL,
    "task_key" character(64) NOT NULL,
    "assignment_authority" character varying(8) NOT NULL,
    "derived_assignment_id" "uuid",
    "source_type" character varying(64) NOT NULL,
    "source_id" "uuid" NOT NULL,
    "source_version" integer NOT NULL,
    "business_occurrence_key" character varying(256) NOT NULL,
    "task_kind" character varying(64) NOT NULL,
    "queue_code" character varying(128) NOT NULL,
    "title" character varying(500) NOT NULL,
    "kind_label" character varying(128) NOT NULL,
    "source_label" character varying(128) NOT NULL,
    "priority" integer DEFAULT 0 NOT NULL,
    "due_at" timestamp with time zone,
    "assignment_status" character varying(16) NOT NULL,
    "assignment_version" integer NOT NULL,
    "assignee_id" "uuid",
    "assignee_display" character varying(200),
    "claimed_at" timestamp with time zone,
    "started_at" timestamp with time zone,
    "blocked_reason" character varying(1000),
    "blocked_until" timestamp with time zone,
    "outcome_code" character varying(64),
    "outcome_source_version" integer,
    "outcome_at" timestamp with time zone,
    "source_deep_link" character varying(512),
    "projection_version" integer NOT NULL,
    "content_hash" character(64) NOT NULL,
    "created_at" timestamp with time zone DEFAULT "clock_timestamp"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "clock_timestamp"() NOT NULL,
    CONSTRAINT "ck_biz_property_task_projection_active" CHECK (((("assignment_status")::"text" <> ALL ((ARRAY['claimed'::character varying, 'in_progress'::character varying, 'blocked'::character varying])::"text"[])) OR (("assignee_id" IS NOT NULL) AND ("assignee_display" IS NOT NULL) AND ("claimed_at" IS NOT NULL)))),
    CONSTRAINT "ck_biz_property_task_projection_authority" CHECK ((((("assignment_authority")::"text" = 'derived'::"text") AND ("derived_assignment_id" IS NOT NULL)) OR ((("assignment_authority")::"text" = 'owning'::"text") AND ("derived_assignment_id" IS NULL)))),
    CONSTRAINT "ck_biz_property_task_projection_blocked" CHECK (((("assignment_status")::"text" = 'blocked'::"text") = ("blocked_reason" IS NOT NULL))),
    CONSTRAINT "ck_biz_property_task_projection_keys" CHECK ((("task_key" ~ '^[0-9a-f]{64}$'::"text") AND ("content_hash" ~ '^[0-9a-f]{64}$'::"text") AND ("length"("btrim"(("business_occurrence_key")::"text")) > 0) AND (("business_occurrence_key")::"text" !~ '[\t\n\r]'::"text") AND (("queue_code")::"text" ~ '^[a-z][a-z0-9._:-]{0,127}$'::"text"))),
    CONSTRAINT "ck_biz_property_task_projection_lifecycle" CHECK ((((("assignment_status")::"text" <> 'claimed'::"text") OR (("started_at" IS NULL) AND ("blocked_reason" IS NULL) AND ("blocked_until" IS NULL))) AND ((("assignment_status")::"text" <> 'in_progress'::"text") OR (("started_at" IS NOT NULL) AND ("blocked_reason" IS NULL) AND ("blocked_until" IS NULL))) AND ((("assignment_status")::"text" <> 'blocked'::"text") OR ("started_at" IS NOT NULL)) AND ((("assignment_status")::"text" <> ALL ((ARRAY['closed'::character varying, 'cancelled'::character varying])::"text"[])) OR (("assignee_id" IS NULL) AND ("assignee_display" IS NULL) AND ("blocked_reason" IS NULL) AND ("blocked_until" IS NULL))))),
    CONSTRAINT "ck_biz_property_task_projection_logical_time" CHECK (("updated_at" >= "created_at")),
    CONSTRAINT "ck_biz_property_task_projection_open" CHECK (((("assignment_status")::"text" <> 'open'::"text") OR (("assignee_id" IS NULL) AND ("assignee_display" IS NULL) AND ("claimed_at" IS NULL) AND ("started_at" IS NULL) AND ("blocked_until" IS NULL)))),
    CONSTRAINT "ck_biz_property_task_projection_outcome" CHECK ((((("assignment_status")::"text" = ANY ((ARRAY['closed'::character varying, 'cancelled'::character varying])::"text"[])) = (("outcome_code" IS NOT NULL) AND ("outcome_source_version" IS NOT NULL) AND ("outcome_at" IS NOT NULL))) AND (("outcome_source_version" IS NULL) OR ("outcome_source_version" > 0)))),
    CONSTRAINT "ck_biz_property_task_projection_positive" CHECK ((("source_version" > 0) AND ("assignment_version" > 0) AND ("projection_version" > 0) AND (("priority" >= 0) AND ("priority" <= 100)))),
    CONSTRAINT "ck_biz_property_task_projection_status" CHECK ((("assignment_status")::"text" = ANY ((ARRAY['open'::character varying, 'claimed'::character varying, 'in_progress'::character varying, 'blocked'::character varying, 'closed'::character varying, 'cancelled'::character varying])::"text"[])))
);


