    "result_hash" character(64) NOT NULL,
    "content_hash" character(64) NOT NULL,
    "occurred_at" timestamp with time zone DEFAULT "clock_timestamp"() NOT NULL,
    CONSTRAINT "ck_biz_property_task_projection_rebuild_audit_counts" CHECK ((("projected_task_count" >= 0) AND ("assignment_mutation_count" = 0))),
    CONSTRAINT "ck_biz_property_task_projection_rebuild_audit_hashes" CHECK ((("request_hash" ~ '^[0-9a-f]{64}$'::"text") AND ("result_hash" ~ '^[0-9a-f]{64}$'::"text") AND ("content_hash" ~ '^[0-9a-f]{64}$'::"text"))),
    CONSTRAINT "ck_biz_property_task_projection_rebuild_audit_mode_action" CHECK ((((("replace_mode")::"text" = 'manual-rebuild'::"text") AND (("command_action")::"text" = 'property.task.rebuild'::"text")) OR ((("replace_mode")::"text" = 'authority-sync'::"text") AND (("command_action")::"text" = ANY ((ARRAY['property.task.claim'::character varying, 'property.task.start'::character varying, 'property.task.block'::character varying, 'property.task.unblock'::character varying, 'property.task.release'::character varying, 'property.task.source-terminal.closed'::character varying, 'property.task.source-terminal.cancelled'::character varying])::"text"[]))))),
    CONSTRAINT "ck_biz_property_task_projection_rebuild_audit_reason" CHECK ((("length"("btrim"(("reason")::"text")) > 0) AND ((("replace_mode")::"text" = 'manual-rebuild'::"text") OR (("reason")::"text" = ('authority-sync:'::"text" || ("command_action")::"text"))))),
    CONSTRAINT "ck_biz_property_task_projection_rebuild_audit_result_ref" CHECK ((((("replace_mode")::"text" = 'manual-rebuild'::"text") AND (("command_action")::"text" = 'property.task.rebuild'::"text") AND ("business_result_version" = "to_projection_version") AND (("result_ref")::"text" = ((((('property-task-rebuild/'::"text" || ("source_type")::"text") || '/'::"text") || "lower"(("source_id")::"text")) || '/v'::"text") || ("business_result_version")::"text"))) OR ((("replace_mode")::"text" = 'authority-sync'::"text") AND (("command_action")::"text" = ANY ((ARRAY['property.task.claim'::character varying, 'property.task.start'::character varying, 'property.task.block'::character varying, 'property.task.unblock'::character varying, 'property.task.release'::character varying])::"text"[])) AND (("result_ref")::"text" ~ (('^property-task/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/v'::"text" || ("business_result_version")::"text") || '$'::"text"))) OR ((("replace_mode")::"text" = 'authority-sync'::"text") AND (("command_action")::"text" = 'property.task.source-terminal.closed'::"text") AND (("result_ref")::"text" = ((((('property-task-source-terminal/'::"text" || ("source_type")::"text") || '/'::"text") || "lower"(("source_id")::"text")) || '/closed/v'::"text") || ("business_result_version")::"text"))) OR ((("replace_mode")::"text" = 'authority-sync'::"text") AND (("command_action")::"text" = 'property.task.source-terminal.cancelled'::"text") AND (("result_ref")::"text" = ((((('property-task-source-terminal/'::"text" || ("source_type")::"text") || '/'::"text") || "lower"(("source_id")::"text")) || '/cancelled/v'::"text") || ("business_result_version")::"text"))))),
    CONSTRAINT "ck_biz_property_task_projection_rebuild_audit_version" CHECK ((("from_projection_version" >= 0) AND ("to_projection_version" = ("from_projection_version" + 1)) AND ("business_result_version" > 0)))
);


