CREATE TABLE "public"."sys_property_permission_bundle" (
    "id" "uuid" DEFAULT "public"."uuid_generate_v4"() NOT NULL,
    "bundle_code" character varying(128) NOT NULL,
    "bundle_name" character varying(100) NOT NULL,
    "definition_version" integer DEFAULT 1 NOT NULL,
    "definition_hash" character(64) NOT NULL,
    "status" character varying(16) DEFAULT 'enabled'::character varying NOT NULL,
    "create_time" timestamp with time zone DEFAULT "clock_timestamp"() NOT NULL,
    "update_time" timestamp with time zone DEFAULT "clock_timestamp"() NOT NULL,
    "is_deleted" boolean DEFAULT false NOT NULL,
    "version" integer DEFAULT 1 NOT NULL,
    "remark" character varying(500),
    CONSTRAINT "ck_sys_property_permission_bundle_code" CHECK ((("bundle_code")::"text" ~ '^property-bundle:[a-z][a-z0-9-]*$'::"text")),
    CONSTRAINT "ck_sys_property_permission_bundle_hash" CHECK (("definition_hash" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "ck_sys_property_permission_bundle_status" CHECK ((("status")::"text" = ANY ((ARRAY['enabled'::character varying, 'disabled'::character varying])::"text"[]))),
    CONSTRAINT "ck_sys_property_permission_bundle_versions" CHECK ((("definition_version" > 0) AND ("version" > 0)))
);


