--
-- Name: sys_property_runtime_control; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."sys_property_runtime_control" (
    "id" "uuid" DEFAULT "public"."uuid_generate_v4"() NOT NULL,
    "tenant_id" character varying(64) NOT NULL,
    "park_id" character varying(64) NOT NULL,
    "control_key" character varying(128) NOT NULL,
    "control_kind" character varying(32) NOT NULL,
    "target" character varying(64) NOT NULL,
    "adapter_version" integer,
    "contract_hash" character(64) NOT NULL,
    "enabled" boolean DEFAULT false NOT NULL,
    "control_mode" character varying(16) DEFAULT 'disabled'::character varying NOT NULL,
    "enabled_by" "uuid",
    "enabled_at" timestamp with time zone,
    "approval_reference" character varying(256),
    "disabled_reason" character varying(500) DEFAULT 'expand-only'::character varying NOT NULL,
    "create_time" timestamp with time zone DEFAULT "clock_timestamp"() NOT NULL,
    "update_time" timestamp with time zone DEFAULT "clock_timestamp"() NOT NULL,
    "version" integer DEFAULT 1 NOT NULL,
    CONSTRAINT "ck_sys_property_runtime_control_disabled" CHECK (((("enabled" = false) AND (("control_mode")::"text" = 'disabled'::"text") AND ("enabled_by" IS NULL) AND ("enabled_at" IS NULL)) OR (("enabled" = true) AND (("control_mode")::"text" <> 'disabled'::"text") AND ("enabled_by" IS NOT NULL) AND ("enabled_at" IS NOT NULL) AND ("approval_reference" IS NOT NULL)))),
    CONSTRAINT "ck_sys_property_runtime_control_hash" CHECK (("contract_hash" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "ck_sys_property_runtime_control_kind" CHECK ((("control_kind")::"text" = ANY ((ARRAY['compatibility_read'::character varying, 'compatibility_write'::character varying, 'change_capture'::character varying, 'mutation_replay'::character varying, 'shadow_compare'::character varying, 'enforce'::character varying])::"text"[]))),
    CONSTRAINT "ck_sys_property_runtime_control_mode" CHECK ((("control_mode")::"text" = ANY ((ARRAY['disabled'::character varying, 'observe'::character varying, 'shadow'::character varying, 'enforce'::character varying])::"text"[]))),
    CONSTRAINT "ck_sys_property_runtime_control_target" CHECK ((("target")::"text" = ANY ((ARRAY['identity'::character varying, 'approval'::character varying, 'event_notification'::character varying, 'task'::character varying, 'property_foundation'::character varying, 'homestay'::character varying, 'housing'::character varying])::"text"[]))),
    CONSTRAINT "ck_sys_property_runtime_control_version" CHECK ((("version" > 0) AND (("adapter_version" IS NULL) OR ("adapter_version" > 0))))
);


