--
-- Name: sys_property_runtime_control_contract_audit; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."sys_property_runtime_control_contract_audit" (
    "id" "uuid" DEFAULT "public"."uuid_generate_v4"() NOT NULL,
    "tenant_id" character varying(64) NOT NULL,
    "park_id" character varying(64) NOT NULL,
    "control_id" "uuid" NOT NULL,
    "control_key" character varying(128) NOT NULL,
    "correction_key" character varying(64) DEFAULT 'b2a-contract-correction-000194'::character varying NOT NULL,
    "old_contract_hash" character(64) NOT NULL,
    "new_contract_hash" character(64) NOT NULL,
    "old_version" integer NOT NULL,
    "new_version" integer NOT NULL,
    "old_disabled_reason" character varying(500) NOT NULL,
    "new_disabled_reason" character varying(500) NOT NULL,
    "old_update_time" timestamp with time zone NOT NULL,
    "new_update_time" timestamp with time zone NOT NULL,
    "evidence_hash" character(64) NOT NULL,
    "occurred_at" timestamp with time zone NOT NULL,
    CONSTRAINT "ck_sys_property_runtime_control_contract_audit_hashes" CHECK ((("old_contract_hash" ~ '^[0-9a-f]{64}$'::"text") AND ("new_contract_hash" ~ '^[0-9a-f]{64}$'::"text") AND ("evidence_hash" ~ '^[0-9a-f]{64}$'::"text"))),
    CONSTRAINT "ck_sys_property_runtime_control_contract_audit_key" CHECK ((("correction_key")::"text" = ANY (ARRAY[('b2a-contract-correction-000194'::character varying)::"text", ('b2a-contract-correction-000195'::character varying)::"text"]))),
    CONSTRAINT "ck_sys_property_runtime_control_contract_audit_times" CHECK ((("new_update_time" = "occurred_at") AND ("new_update_time" >= "old_update_time"))),
    CONSTRAINT "ck_sys_property_runtime_control_contract_audit_versions" CHECK ((("old_version" > 0) AND ("new_version" = ("old_version" + 1))))
);


